  function langLabel(){ return LANG==="ar" ? "English" : "العربية"; }
  function applyLang(){ try{ var d=document.documentElement; d.setAttribute("lang", LANG==="ar"?"ar":"en"); d.setAttribute("dir", LANG==="ar"?"rtl":"ltr"); }catch(e){} }
  function setLang(l){ LANG = (l==="ar"?"ar":"en"); try{ localStorage.setItem(LANG_KEY, LANG); }catch(e){} applyLang(); rerender(); }
  function toggleLang(){ setLang(LANG==="ar"?"en":"ar"); }

  var root = document.getElementById("root");

  function esc(s){ return String(s==null?"":s).replace(/[&<>"]/g,function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]; }); }
  function redInto(node, where, e){
    try{ var d=document.createElement("div"); d.className="err"; d.textContent="ERROR ("+where+"): "+((e&&e.message)||e); node.appendChild(d); }catch(x){}
  }
  function redFull(where, e){ try{ root.innerHTML=""; redInto(root, where, e); }catch(x){} }
  // Any uncaught error becomes visible red text too, never a black screen.
  window.addEventListener("error", function(ev){ try{ redInto(root, "uncaught", (ev&&ev.error)||(ev&&ev.message)||"error"); }catch(x){} });
  window.addEventListener("unhandledrejection", function(ev){ try{ redInto(root, "promise", (ev&&ev.reason)||"promise rejected"); }catch(x){} });

  // ---- durable session (a clone of the supabase.js session layer): __memSession is memory-primary; the
  //      localStorage mirror is best-effort and NEVER gates success. bearer() falls back to anon. ----
  var __memSession = null, __mirrorOk = null;
  function session(){
    if(__memSession) return __memSession;
    try{ var s=JSON.parse(localStorage.getItem(SESSION_KEY)||"null"); if(s) __memSession=s; return s; }catch(e){ return null; }
  }
  function setSession(s){
    __memSession = s || null;
    try{ if(s) localStorage.setItem(SESSION_KEY, JSON.stringify(s)); else localStorage.removeItem(SESSION_KEY); __mirrorOk=true; }
    catch(e){ __mirrorOk=false; }   // a mirror failure is recorded, never thrown
  }
  function signedIn(){ var s=session(); return !!(s && s.access_token); }     // warm-boot routing only
  function bearer(){ var s=session(); return (s && s.access_token) ? s.access_token : ANON; }
  function authEmail(){ var s=session(); return (s && s.email) || ""; }
  function expired(s){ try{ if(!s || !s.expires_at) return false; return (Number(s.expires_at)*1000) < (Date.now()-5000); }catch(e){ return false; } }

  // Bounded fetch: an independent setTimeout race, not the AbortController, guarantees the promise settles
  // (WebKit's AbortController+fetch is unreliable). Body read via arrayBuffer + TextDecoder, BOM stripped.
  function timeoutError(ms){ var e=new Error("request timed out after "+ms+"ms"); e.kind="timeout"; return e; }
  function authFetchOnce(url, opts){
    var to={};
    var race=new Promise(function(_,rej){ to.timer=setTimeout(function(){ to.fired=true; rej(timeoutError(FETCH_TIMEOUT_MS)); }, FETCH_TIMEOUT_MS); });
    var run=(async function(){
      var res=await fetch(url, opts);
      var text=(typeof res.arrayBuffer==="function") ? new TextDecoder("utf-8").decode(await res.arrayBuffer()) : await res.text();
      text=String(text||""); if(text.charCodeAt(0)===0xFEFF) text=text.slice(1); text=text.trim();
      var data=null, parseFailed=false; if(text){ try{ data=JSON.parse(text); }catch(e){ parseFailed=true; } }
      return { res:res, text:text, data:data, parseFailed:parseFailed };
    })();
    return Promise.race([run, race]).then(
      function(v){ clearTimeout(to.timer); return v; },
      function(e){ clearTimeout(to.timer); try{ run.catch(function(){}); }catch(x){} if(e && !e.kind) e.kind="network"; throw e; }
    );
  }
  function tokenPost(grant, payload){
    return authFetchOnce(URL_BASE + "/auth/v1/token?grant_type=" + grant, {
      method:"POST", headers:{ "apikey": ANON, "Content-Type":"application/json" }, body: JSON.stringify(payload), cache:"no-store"
    });
  }
  // signIn returns the parsed session; STORING it is not a precondition of returning. Typed throws for the
  // sign-in card to branch on (empty / parse / auth / unavailable / timeout / network).
  function signIn(email, password){
    return tokenPost("password", { email:email, password:password }).then(function(r){
      if(r.res.ok && r.text.length===0){ var ee=new Error("empty response body"); ee.kind="empty"; throw ee; }
      if(r.res.ok && r.parseFailed){ var pe=new Error("response could not be parsed"); pe.kind="parse"; throw pe; }
      var d=r.data;
      if(!r.res.ok || !d || !d.access_token){
        var err=new Error((d && (d.error_description||d.msg||d.message)) || ("HTTP "+r.res.status));
        err.kind = (r.res.status>=500) ? "unavailable" : "auth"; throw err;
      }
      var sess={ access_token:d.access_token, refresh_token:d.refresh_token, expires_at:d.expires_at, email:email, uid:(d.user&&d.user.id)||"" };
      setSession(sess);   // memory-primary; the mirror is best-effort and never gates this return
      return sess;
    });
  }
  function refresh(){
    var s=session(); if(!s || !s.refresh_token) return Promise.resolve(false);
    return tokenPost("refresh_token", { refresh_token:s.refresh_token }).then(function(r){
      if(r.res.ok && r.data && r.data.access_token){
        setSession({ access_token:r.data.access_token, refresh_token:r.data.refresh_token, expires_at:r.data.expires_at, email:s.email, uid:s.uid||((r.data.user&&r.data.user.id)||"") });
        return true;
      }
      if(r.res.status===400 || r.res.status===401) setSession(null);   // definitive rejection only; a blip keeps it
      return false;
    }, function(){ return false; });
  }
  function signOut(){
    var s=session();
    var p = (s && s.access_token)
      ? fetch(URL_BASE+"/auth/v1/logout", { method:"POST", headers:{ "apikey":ANON, "Authorization":"Bearer "+s.access_token }, cache:"no-store" }).then(function(){}, function(){})
      : Promise.resolve();
    return p.then(function(){ setSession(null); });
  }

  // One REST GET of console_board with bearer() + apikey; one refresh-and-retry on 401/403 (rest() discipline).
  function fetchBoard(retried){
    return fetch(URL_BASE + "/rest/v1/console_board?" + QUERY, {
      method:"GET", headers:{ "apikey": ANON, "Authorization": "Bearer " + bearer() }, cache:"no-store"
    }).then(function(res){
      if((res.status===401 || res.status===403) && !retried && session() && session().refresh_token){
        return refresh().then(function(ok){ if(ok) return fetchBoard(true); var e=new Error("auth"); e.authRequired=true; throw e; });
      }
      return res.text().then(function(tx){
        var d=null; try{ d = tx ? JSON.parse(tx) : null; }catch(e){}
        if(!res.ok){ var e2=new Error((d && d.message) || ("HTTP "+res.status)); if(res.status===401||res.status===403) e2.authRequired=true; throw e2; }
        return Array.isArray(d) ? d : [];
      });
    });
  }

  // L2 reply detail comes from console_inbound (the reply resolver read path: repliesForOpp / replyCountFor).
  // The board STAGE still comes only from console_board; this read adds reply COUNTS, never a stage. Best-effort:
  // if it fails the board still renders and replies just do not show. Bearer + apikey, read-only.
  function fetchInbound(){
    return fetch(URL_BASE + "/rest/v1/console_inbound?select=id,opp,kind,bounce,ts,data&order=ts.asc", {
      method:"GET", headers:{ "apikey": ANON, "Authorization": "Bearer " + bearer() }, cache:"no-store"
    }).then(function(res){
      if(!res.ok) return [];
      return res.text().then(function(tx){ var d=null; try{ d=tx?JSON.parse(tx):null; }catch(e){} return Array.isArray(d)?d:[]; });
    }, function(){ return []; });
  }
  // L3 detail reads (best-effort, scoped to ONE opp, ONLY on drawer open): the opportunity RECORD (console_opps,
  // for its carried notes - there is NO server-side accrued-memory store), its SENDS (console_mail) and OPENS
  // (console_hits) for the activity timeline and the Thrive->prospect side of the thread. Any failure degrades to
  // empty; the drawer's heart (the reply thread + the counts) already comes from the in-memory board row and the
  // ONE reply resolver, so it never depends on these. Bearer + apikey, read-only. PRIVACY: prospect addresses/
  // names/reply text are read LIVE here and only displayed - never written to storage, a log, or any artifact.
  function enc(s){ return encodeURIComponent(String(s==null?"":s)); }
  function restGet(path){
    return fetch(URL_BASE + "/rest/v1/" + path, {
      method:"GET", headers:{ "apikey": ANON, "Authorization": "Bearer " + bearer() }, cache:"no-store"
    }).then(function(res){ if(!res.ok) return []; return res.text().then(function(tx){ var d=null; try{ d=tx?JSON.parse(tx):null; }catch(e){} return Array.isArray(d)?d:[]; }); }, function(){ return []; });
  }
  function fetchDetail(slug){
    return Promise.all([
      restGet("console_opps?slug=eq."+enc(slug)+"&select=slug,data&limit=1"),
      restGet("console_mail?opp=eq."+enc(slug)+"&select=id,opp,ts,data&order=ts.asc"),
      restGet("console_hits?slug=eq."+enc(slug)+"&select=id,slug,ts,data&order=ts.asc")
    ]).then(function(a){ return { opp:(a[0]||[])[0]||null, mail:a[1]||[], hits:a[2]||[] }; }, function(){ return { opp:null, mail:[], hits:[] }; });
  }
  // ---- L4 WRITE path (cloned from the engine's console_opps upsert; NEVER a rewrite of the read path). The
  //      engine wrote a WHOLE opp record via POST resolution=merge-duplicates because it held the full record.
  //      The standalone board holds only the console_board VIEW row (partial), so it writes a partial PATCH to
  //      console_opps by slug: PATCH can never insert a stub row and never touches a column it does not name, so
  //      business / data / a sibling column is safe. Every write goes through authFetchOnce, so the promise ALWAYS
  //      settles (a stalled write REJECTS on the setTimeout race, never a hung promise), and it reuses the exact
  //      bearer + apikey + one-refresh-retry discipline of the reads. NO storage is touched on the write path. ----
  function oppPatch(slug, patch, retried){
    var url = URL_BASE + "/rest/v1/console_opps?slug=eq." + enc(slug);
    return authFetchOnce(url, {
      method:"PATCH",
      headers:{ "apikey":ANON, "Authorization":"Bearer "+bearer(), "Content-Type":"application/json", "Prefer":"return=minimal" },
      cache:"no-store", body: JSON.stringify(patch)
    }).then(function(r){
      if((r.res.status===401 || r.res.status===403) && !retried && session() && session().refresh_token){
        return refresh().then(function(ok){ if(ok) return oppPatch(slug, patch, true); var e=new Error("auth"); e.authRequired=true; throw e; });
      }
      if(!r.res.ok){ var e2=new Error((r.data && r.data.message) || ("HTTP "+r.res.status)); if(r.res.status===401||r.res.status===403) e2.authRequired=true; throw e2; }
      return true;                                                     // confirmed: the server holds the change
    });
  }
  // Strict read of the opp record's data jsonb (for the note read-modify-write). Unlike restGet (best-effort,
  // returns [] on failure), this REJECTS on a failed read so a note write never appends onto a guessed-empty
  // object and clobbers the real notes. Settles via authFetchOnce (timeout REJECTS, never hangs).
  function oppReadData(slug, retried){
    var url = URL_BASE + "/rest/v1/console_opps?slug=eq." + enc(slug) + "&select=slug,data&limit=1";
    return authFetchOnce(url, {
      method:"GET", headers:{ "apikey":ANON, "Authorization":"Bearer "+bearer() }, cache:"no-store"
    }).then(function(r){
      if((r.res.status===401 || r.res.status===403) && !retried && session() && session().refresh_token){
        return refresh().then(function(ok){ if(ok) return oppReadData(slug, true); var e=new Error("auth"); e.authRequired=true; throw e; });
      }
      if(!r.res.ok){ var e2=new Error((r.data && r.data.message) || ("HTTP "+r.res.status)); if(r.res.status===401||r.res.status===403) e2.authRequired=true; throw e2; }
      var rows = Array.isArray(r.data) ? r.data : [];
      return (rows[0] && rows[0].data && typeof rows[0].data==="object") ? rows[0].data : {};
    });
  }
  function isoNow(){ try{ return new Date().toISOString(); }catch(e){ return ""; } }
  // Add a note to the opp RECORD (console_opps.data.notes[]), read-modify-write so a concurrent note is not lost,
  // then re-read to CONFIRM the note landed (the count grew). The note author is the signed-in OPERATOR's uid
  // (Step 1: currentUid(), matching the engine's currentActor()=authUid() and the profile tables' key), never a
  // prospect; resolveActor() turns it (or a legacy email row) into a name on read. Returns the confirmed notes.
  function addNote(slug, text){
    return oppReadData(slug).then(function(data){
      var notes = Array.isArray(data.notes) ? data.notes.slice() : [];
      var before = notes.length;
      notes.push({ ts:isoNow(), text:String(text||""), by:currentUid() });
      var next = Object.assign({}, data, { notes:notes });
      return oppPatch(slug, { data:next, up:Date.now() }).then(function(){
        return oppReadData(slug).then(function(d2){                     // read-back confirm
          var got = Array.isArray(d2.notes) ? d2.notes : [];
          if(got.length <= before){ throw new Error("note did not persist"); }
          return got;
        });
      });
    });
  }
