  function normFrom(s){ return String(s==null?"":s).trim().toLowerCase(); }
  // One resolver, linked-everywhere-or-nowhere (§3): a reply belongs to a card ONLY by its stored resolved opp
  // (the server attributed it on write); auto-replies and bounces move no card; dedup by sender keeping the
  // earliest, sort, number 1..N. An unattributed human reply is inbox backlog (feeds the inbound-health pill).
  function buildReplies(inbound){
    var byOpp={}, waiting=0;
    (Array.isArray(inbound)?inbound:[]).forEach(function(r){ try{
      r=r||{}; var data=r.data||{};
      if(r.kind==="auto" || r.bounce) return;
      var opp=r.opp||"";
      if(!opp){ waiting++; return; }
      var from=normFrom(data.from||r.from), ts=String(r.ts||data.ts||"");
      var g=byOpp[opp]||(byOpp[opp]={});
      var key=from||("_"+ts);
      // Keep a snippet for the L3 drawer thread (never changes the count/numbering; still one resolver).
      if(!g[key] || ts < g[key].ts) g[key]={ from:from, ts:ts, subject:(data.subject||""), snippet:(data.snippet||data.body||data.text||"") };
    }catch(e){} });
    var count={}, list={};
    Object.keys(byOpp).forEach(function(slug){
      var items=Object.keys(byOpp[slug]).map(function(k){ return byOpp[slug][k]; }).sort(function(a,b){ return a.ts<b.ts?-1:(a.ts>b.ts?1:0); });
      items.forEach(function(it,i){ it.num=i+1; });
      count[slug]=items.length; list[slug]=items;
    });
    return { count:count, list:list, waiting:waiting };
  }
  // new-activity (paintCardBadges spirit): per-card last-seen last_activity_ts, device-local. A card is "new"
  // only if it was seen before AND its activity is newer; a first view marks nothing new.
  function readSeen(){ try{ return JSON.parse(localStorage.getItem(SEEN_KEY)||"{}")||{}; }catch(e){ return {}; } }
  function writeSeen(m){ try{ localStorage.setItem(SEEN_KEY, JSON.stringify(m||{})); }catch(e){} }
  function countUpAll(){
    try{
      var els=root.querySelectorAll("[data-countup]");
      [].forEach.call(els, function(el){
        var to=Number(el.getAttribute("data-countup"))||0, dur=520, t0=null;
        if(to<=0){ el.textContent="0"; return; }
        function step(ts){ if(t0===null) t0=ts; var p=Math.min(1,(ts-t0)/dur); el.textContent=String(Math.round(p*to)); if(p<1) requestAnimationFrame(step); else el.textContent=String(to); }
        requestAnimationFrame(step);
      });
    }catch(e){}
  }

  // ---- views (localized; a lang toggle sits on the sign-in card and in the board header) ----
  var VIEW = "signin", __data = null;
  function langBtn(){ return '<button class="link" id="langBtn" type="button">' + esc(langLabel()) + '</button>'; }
  function rerender(){ if(VIEW==="board" && __data){ renderBoard(__data); } else if(VIEW==="board"){ loadBoard(); } else { signinView(); } }

  function signinView(){
    VIEW="signin"; applyLang();
    root.innerHTML =
      '<div class="signin">' +
      '<h1>' + esc(t("title")) + '</h1>' +
      '<p>' + esc(t("sub")) + '</p>' +
      '<input id="em" type="email" autocomplete="username" spellcheck="false" placeholder="' + esc(t("email")) + '">' +
      '<input id="pw" type="password" autocomplete="current-password" placeholder="' + esc(t("pass")) + '">' +
      '<button id="go" class="primary" type="button">' + esc(t("go")) + '</button>' +
      '<div id="siErr"></div>' +
      '<p style="margin:14px 0 0">' + langBtn() + '</p>' +
      '</div>';
    var em=document.getElementById("em"), pw=document.getElementById("pw"), go=document.getElementById("go"), er=document.getElementById("siErr");
    var lb=document.getElementById("langBtn"); if(lb) lb.addEventListener("click", toggleLang);
    setTimeout(function(){ try{ em.focus(); }catch(e){} }, 40);
    function submit(){
      er.innerHTML="";
      var e=(em.value||"").trim(), p=pw.value||"";
      if(!e || !p){ redInto(er, "sign-in", new Error(t("fill"))); return; }
      go.disabled=true; go.textContent=t("busy");
      signIn(e, p).then(function(){ loadBoard(); })
        .catch(function(ex){
          go.disabled=false; go.textContent=t("go"); er.innerHTML="";
          var kind=(ex&&ex.kind)||"auth";
          redInto(er, "sign-in", new Error((kind==="timeout"||kind==="network"||kind==="unavailable") ? t("net") : t("err")));
        });
    }
    go.addEventListener("click", submit);
    pw.addEventListener("keydown", function(ev){ if(ev.key==="Enter") submit(); });
  }

  // Operator chip (signed-in email) + language toggle + refresh + sign-out.
  function headerHtml(){
    return '<div class="top" style="padding:8px 2px">' +
      '<span class="muted" id="opChip">' + esc(authEmail()) + '</span>' +
      '<span class="row-actions">' + langBtn() +
        // Step 2D: the Admin executive surface is a SEPARATE header entry, hidden by default and revealed only
        // for an owner. isOwner() resolves async (loadIdentity), so paintAdminSlot() runs both now and again
        // from finishIdentity once the role settles. A member never sees this control, and openAdmin() is a
        // no-op for a non-owner besides, so the real gate stays the RLS policy on the write.
        // E1: New message opens the editor as its own overlay (compose to any recipient, with or without an
        // opp link). Visible to every signed-in operator, beside Profile.
        '<button class="link" id="newMsgBtn" type="button">' + esc(t("nm_open")) + '</button>' +
        '<button class="link" id="adminBtn" type="button" hidden>' + esc(t("adm_open")) + '</button>' +
        '<button class="link" id="profileBtn" type="button">' + esc(t("pf_open")) + '</button>' +
        '<button class="link" id="reload" type="button">' + esc(t("refresh")) + '</button>' +
        '<button class="link" id="signout" type="button">' + esc(t("signout")) + '</button>' +
      '</span></div>';
  }
  // Reveal the Admin entry only for an owner. Safe to call repeatedly (idempotent) and before the role settles.
  function paintAdminSlot(){
    var ab=document.getElementById("adminBtn"); if(!ab) return;
    var owner=false; try{ owner = (typeof isOwner==="function") && isOwner(); }catch(e){}
    ab.hidden = !owner;
  }
  try{ window.__thrivePaintAdminSlot = paintAdminSlot; }catch(e){}
  function wireHeader(){
    var lb=document.getElementById("langBtn"); if(lb) lb.addEventListener("click", toggleLang);
    var nm=document.getElementById("newMsgBtn"); if(nm) nm.addEventListener("click", function(){ openNewMessage(); });   // E1
    var ab=document.getElementById("adminBtn"); if(ab) ab.addEventListener("click", function(){ openAdmin(); });   // Step 2D
    var pb=document.getElementById("profileBtn"); if(pb) pb.addEventListener("click", function(){ openProfile(); });   // Step 2B
    var rl=document.getElementById("reload"); if(rl) rl.addEventListener("click", function(){ loadBoard(); });
    var so=document.getElementById("signout"); if(so) so.addEventListener("click", function(){ signOut().then(signinView); });
    paintAdminSlot();
  }

  // Bucket by the SERVER stage only (never derived here). Domain law: a REPLIED opp is a terminal-success story
  // and stays in Replied even once archived - archiving is end-of-conversation, NOT exclusion, so it must never
  // subtract from the replied stage count. Every OTHER archived opp (and won/lost/dropped) belongs to the tray;
  // the archived tray is rebuilt separately below from the archived flag, so a replied+archived opp shows in BOTH
  // its Replied lane and the closed shelf. "other" must end empty.
  function laneOf(row){
    var st=(row && row.stage) || "";
    if(st==="replied") return "replied";
    if(row && row.archived) return "tray";
    if(BOARD_LANES.indexOf(st)>=0) return st;
    if(TRAY_STAGES.indexOf(st)>=0) return "tray";
    return "other";
  }
  // A card. The NAME (business) is shown in BOTH languages, never the slug (the slug is only a last resort when
  // an opp has no business at all). Counts/opens/idle and the reply N-badge come from the server; no stage math.
  function cardHtml(row){
    row = row || {};
    var slug = row.slug || "";
    var biz = esc(row.business || row.slug || t("unnamed"));
    var isNew = (__seen && (slug in __seen)) && (String(row.last_activity_ts||"") > String(__seen[slug]||""));
    var rc = (__reps && __reps.count && __reps.count[slug]) || 0;
    var bits = [];
    var sc = Number(row.sent_count||0), oc = Number(row.open_count||0);
    if(sc) bits.push(sc + " " + t(sc===1 ? "b_send" : "b_sends"));
    if(oc) bits.push(oc + " " + t(oc===1 ? "b_open" : "b_opens"));
    if(row.idle_days!=null && row.idle_days!=="") bits.push(row.idle_days + t("b_idle"));
    var badges = "";
    if(row.has_page)  badges += '<span class="badge">' + esc(t("bg_page")) + '</span>';
    if(row.has_email) badges += '<span class="badge">' + esc(t("bg_email")) + '</span>';
    if(row.archived)  badges += '<span class="badge">' + esc(t("bg_archived")) + '</span>';
    var nb  = rc ? ' <span class="nbadge" title="' + esc(t("b_replies")) + '">' + rc + '</span>' : '';
    var dot = isNew ? '<span class="newdot" aria-hidden="true"></span>' : '';
    var sendmark = row.__sending ? '<span class="sendmark">' + esc(t("s_sending")) + '</span>' : '';   // L5 optimistic send-in-flight
    var reps = "";
    if(rc && __reps.list && __reps.list[slug]){
      // reply grouping (replyGroupHtml spirit): numbered repliers 1..N, the same count as the N-badge.
      reps = '<div class="reps">' + __reps.list[slug].map(function(it){
        return '<div class="rep"><span class="repn">' + it.num + '</span> ' + esc(it.from || t("unnamed")) + '</div>';
      }).join("") + '</div>';
    }
    return '<div class="card" data-slug="' + esc(slug) + '" role="button" tabindex="0">' + dot +
           '<div class="b">' + biz + nb + '</div>' +
           (bits.length ? ('<div class="s">' + esc(bits.join("  \\u00b7  ")) + '</div>') : '') +
           (badges || sendmark ? ('<div>' + sendmark + badges + '</div>') : '') +
           reps +
           '</div>';
  }
  // ---- L3 opportunity detail drawer (read-only): open and view; no edit/send/archive. Cloned from the engine
